22|## 1) Keep-old cache must expire (cause 1)
23|
24|### Goal
25|Stale/dummy ids that are never reconfirmed should not live forever. A TTL + eviction replaces indefinite keep-old.
26|
27|### Example — stale slice evicted after TTL
28|
29|```js
30|// runner/harnessModelDiscovery.ttl.test.js
31|import { describe, it, expect, beforeEach } from "vitest";
32|import { discoveryCache, clearDiscoveryCache, runDiscoveryLeg } from "./harnessModelDiscovery.js";
33|
34|describe("discovery TTL eviction (structural fix)", () => {
35|  beforeEach(() => clearDiscoveryCache());
36|
37|  it("evicts a stale slice that has not been reconfirmed within TTL", async () => {
38|    const TTL_MS = 24 * 3600 * 1000;
39|    // seed a dummy id as if a prior round returned it
40|    discoveryCache["pi"] = {
41|      ids: ["pi::test::dummy-model"],
42|      atMs: Date.now() - (TTL_MS + 1000), // stale
43|      error: null,
44|    };
45|
46|    // next leg fails (timeout) — with the fix, stale slice is evicted, not kept
47|    const res = await runDiscoveryLeg("pi", {
48|      discoverFn: async () => { throw Object.assign(new Error("timeout"), { code: "ETIMEDOUT" }); },
49|      ttlMs: TTL_MS,
50|    });
51|
52|    expect(res.ids).toEqual([]); // evicted, not kept
53|    expect(res.error?.code).toBe("STALE_EVICTED");
54|  });
55|
56|  it("keeps a fresh slice on transient failure within TTL", async () => {
57|    const TTL_MS = 24 * 3600 * 1000;
58|    discoveryCache["pi"] = {
59|      ids: ["pi::mistral::real-model"],
60|      atMs: Date.now() - 1000, // fresh
61|      error: null,
62|    };
63|    const res = await runDiscoveryLeg("pi", {
64|      discoverFn: async () => { throw new Error("transient"); },
65|      ttlMs: TTL_MS,
66|    });
67|    expect(res.ids).toEqual(["pi::mistral::real-model"]);
68|  });
69|});
