21|/**
22| * MARK: Task blocking API integration
23| * @description Verifies the HTTP surface of task dependencies: create/PATCH
24| * validation maps to 400 (self-block, unknown ids, cycles) while
25| * executing a blocked task stays 409, and clearing blockedBy re-enables it.
26| */
27|describe("Task blocking API", () => {
28|	let testProject;
29|
30|	beforeAll(async () => {
31|		await app.ready();
32|		// Dedicated fixture project under the throwaway roots (see top of
33|		// file): task writes stay inside the temp notes space.
34|		const res = await app.inject({
35|			method: "POST",
36|			url: "/projects",
37|			payload: { name: "Task Blocking Test Project", gitUrl: "https://git.example.com/team/fixture.git" },
38|		});
39|		expect(res.statusCode).toBe(201);
40|		testProject = JSON.parse(res.payload);
41|	});
42|
43|	async function activeProject() {
44|		return testProject;
45|	}
46|
47|	async function createTask(projectId, payload) {
48|		const res = await app.inject({
49|			method: "POST",
50|			url: "/tasks",
51|			payload: { projectId, ...payload },
52|		});
53|		return { statusCode: res.statusCode, body: JSON.parse(res.payload) };
54|	}
55|
56|	it("creates a chained task and rejects execution while blocked with 409", async () => {
57|		const project = await activeProject();
58|		const { body: blocker } = await createTask(project.id, {
59|			goal: "Blocking prerequisite",
60|		});
61|		const created = await createTask(project.id, {
62|			goal: "Blocked dependent",
63|			blockedBy: [blocker.id],
64|		});
65|		expect(created.statusCode).toBe(200);
66|		expect(created.body.blockedBy).toEqual([blocker.id]);
67|
68|		const execRes = await app.inject({
69|			method: "POST",
70|			url: `/tasks/${created.body.id}/execute`,
71|			payload: { projectId: project.id },
72|		});
73|		expect(execRes.statusCode).toBe(409);
74|		expect(JSON.parse(execRes.payload).blockedBy).toEqual([blocker.id]);
75|	});
76|
77|	it("rejects create with an unknown blocker id with 400", async () => {
78|		const project = await activeProject();
79|		const created = await createTask(project.id, {
80|			goal: "Typo dependent",
81|			blockedBy: ["task-that-does-not-exist"],
82|		});
83|		expect(created.statusCode).toBe(400);
84|		expect(created.body.error).toMatch("Unknown task ID");
85|	});
86|
87|	it("rejects self-block and cycles on PATCH with 400", async () => {
88|		const project = await activeProject();
89|		const { body: taskA } = await createTask(project.id, {
90|			goal: "Chain A",
91|		});
92|		const { body: taskB } = await createTask(project.id, {
93|			goal: "Chain B",
94|			blockedBy: [taskA.id],
95|		});
96|
97|		const selfRes = await app.inject({
98|			method: "PATCH",
99|			url: `/tasks/${taskB.id}`,
100|			payload: { projectId: project.id, blockedBy: [taskB.id] },
101|		});
102|		expect(selfRes.statusCode).toBe(400);
103|		expect(JSON.parse(selfRes.payload).error).toMatch("itself");
104|
105|		const cycleRes = await app.inject({
106|			method: "PATCH",
107|			url: `/tasks/${taskA.id}`,
108|			payload: { projectId: project.id, blockedBy: [taskB.id] },
109|		});
110|		expect(cycleRes.statusCode).toBe(400);
111|		expect(JSON.parse(cycleRes.payload).error).toMatch("cycle");
112|	});
113|
114|	it("rejects PATCH with an unknown blocker id with 400", async () => {
115|		const project = await activeProject();
116|		const { body: task } = await createTask(project.id, {
117|			goal: "Patch typo check",
118|		});
119|		const res = await app.inject({
120|			method: "PATCH",
121|			url: `/tasks/${task.id}`,
122|			payload: { projectId: project.id, blockedBy: ["no-such-task"] },
123|		});
124|		expect(res.statusCode).toBe(400);
125|	});
126|
127|	it("unblocks execution after the blocker completes and blockedBy clears", async () => {
128|		const project = await activeProject();
129|		const { body: blocker } = await createTask(project.id, {
130|			goal: "Release prerequisite",
131|		});
132|		const { body: blocked } = await createTask(project.id, {
133|			goal: "Released dependent",
134|			blockedBy: [blocker.id],
135|		});
136|
137|		await app.inject({
138|			method: "POST",
139|			url: `/tasks/${blocker.id}/complete`,
140|			payload: { projectId: project.id },
141|		});
142|
143|		const queueRes = await app.inject({
144|			method: "GET",
145|			url: `/tasks/queue?projectId=${project.id}`,
146|		});
147|		const entry = JSON.parse(queueRes.payload).find(
148|			(q) => q.id === blocked.id,
149|		);
150|		expect(entry.isBlocked).toBe(false);
151|	});
152|});

